import ScratchLinkBLE from '../../io/ble';
import WebBLE from '../../io/ble-web';
import JSONRPC from '../../util/jsonrpc';

const ROOT_SERVICE = '48c5d828-ac2a-442d-97a3-0c9822b04979';
const UART_SERVICE = '6e400001-b5a3-f393-e0a9-e50e24dcca9e';
const RX = '6e400002-b5a3-f393-e0a9-e50e24dcca9e';
const TX = '6e400003-b5a3-f393-e0a9-e50e24dcca9e';
const ROOT_DISCOVERY_OPTIONS = {
    filters: [{services: [ROOT_SERVICE]}],
    optionalServices: [UART_SERVICE]
};
const SCRUB_DISCOVERY_ACK_TIMEOUT_MS = 1000;
const SCRUB_DISCOVERY_ACK_ATTEMPTS = 30;
// Web Bluetooth and the Scrub bridge both expose a write promise, but some
// Scratch Link/Scrub versions leave that promise pending after CoreBluetooth
// accepted the packet. Keep the transport-level ordering without making the
// Scratch command wait on that promise forever.
const UART_WRITE_GAP_MS = 60;

const clamp = (value, min, max) => Math.max(min, Math.min(max, Number(value)));

const crc8 = bytes => {
    let crc = 0;
    for (const value of bytes) {
        crc ^= value;
        for (let bit = 0; bit < 8; bit++) crc = (crc & 0x80) ? ((crc << 1) ^ 0x07) & 0xFF : (crc << 1) & 0xFF;
    }
    return crc;
};

const bytesToHex = bytes => Array.from(bytes, value => value.toString(16).padStart(2, '0')).join(' ');

const bytesToUtf8 = bytes => {
    const end = Array.from(bytes).indexOf(0);
    const value = end < 0 ? bytes : bytes.slice(0, end);
    return new TextDecoder().decode(value);
};

// Scratch VM's Base64Util imports the npm `btoa` package, whose browser build
// performs an unguarded Node Buffer check. Buffer is not present in Edge, Safari, or
// WKWebView. Use the browser-native functions directly so command writes work
// in both Web Bluetooth and Scrub.
const bytesToBase64 = bytes => {
    let binary = '';
    for (const value of bytes) binary += String.fromCharCode(value);
    return btoa(binary);
};

const base64ToBytes = base64 => {
    const binary = atob(base64);
    return Uint8Array.from(binary, value => value.charCodeAt(0));
};

const supportsWebBluetooth = (navigatorObject = typeof navigator === 'undefined' ? null : navigator) =>
    Boolean(navigatorObject && navigatorObject.bluetooth &&
        typeof navigatorObject.bluetooth.requestDevice === 'function');

const selectBLEAdapter = navigatorObject => supportsWebBluetooth(navigatorObject) ? WebBLE : ScratchLinkBLE;

const isScratchLinkSocketClass = candidate => Boolean(candidate &&
    typeof candidate === 'function' &&
    typeof candidate.isSafariHelperCompatible === 'function' &&
    candidate.isSafariHelperCompatible());

const getScrubSocketClass = (scope = typeof self === 'undefined' ? null : self) => {
    const publishedSocket = scope && scope.Scratch && scope.Scratch.ScratchLinkSafariSocket;
    if (isScratchLinkSocketClass(publishedSocket)) return publishedSocket;

    // Scrub always injects ScratchLinkKit, but intentionally publishes its Socket
    // only after the standard Scratch marker is present. Xcratch creates that
    // marker after Scrub's document-end script can run, so use the already-loaded
    // class directly without changing Scrub's publication policy.
    try {
        // eslint-disable-next-line no-undef
        const injectedSocket = typeof ScratchLinkKit === 'undefined' ? null : ScratchLinkKit.Socket;
        return isScratchLinkSocketClass(injectedSocket) ? injectedSocket : null;
    } catch (error) {
        return null;
    }
};

/**
 * Scrub's injected Socket supports multiple independent BLE sessions. Do not
 * inherit the VM's default BLE export here: that CommonJS module selects its
 * implementation when the editor bundle loads, and certain WKWebViews expose
 * a partial navigator.bluetooth object. In that situation the default export
 * can be WebBLE even though Scrub's Scratch Link bridge is the usable
 * transport. This self-contained adapter always uses the injected Socket and
 * therefore opens one native BLE session per Root.
 */
class RootScratchLinkBLE extends JSONRPC {
    constructor (runtime, extensionId, peripheralOptions, connectCallback, resetCallback, SocketClass) {
        super();
        this._runtime = runtime;
        this._extensionId = extensionId;
        this._peripheralOptions = peripheralOptions;
        this._connectCallback = connectCallback;
        this._resetCallback = resetCallback;
        this._availablePeripherals = {};
        this._connected = false;
        this._characteristicDidChangeCallback = null;
        this._discoverTimeoutID = null;
        this._scrubDiscoveryAckTimer = null;
        this._scrubDiscoveryAttempt = 0;
        this._socket = new SocketClass('BLE');
        this._socket.setOnOpen(this.requestPeripheral.bind(this));
        this._socket.setOnClose(this.handleDisconnectError.bind(this));
        this._socket.setOnError(this._handleRequestError.bind(this));
        this._socket.setHandleMessage(this._handleMessage.bind(this));
        this._sendMessage = this._socket.sendMessage.bind(this._socket);
        this._socket.open();
    }

    requestPeripheral () {
        this._availablePeripherals = {};
        if (this._discoverTimeoutID) window.clearTimeout(this._discoverTimeoutID);
        this._scrubDiscoveryAttempt = 0;
        this._requestPeripheralWhenScrubIsReady();
    }

    _requestPeripheralWhenScrubIsReady () {
        const requestId = this._requestID;
        const request = this.sendRemoteRequest('discover', this._peripheralOptions);
        const attempt = this._scrubDiscoveryAttempt++;

        this._scrubDiscoveryAckTimer = window.setTimeout(() => {
            if (!this._openRequests[requestId]) return;
            delete this._openRequests[requestId];
            if (attempt + 1 < SCRUB_DISCOVERY_ACK_ATTEMPTS) {
                this._requestPeripheralWhenScrubIsReady();
            } else {
                this._handleRequestError(new Error('Scrub BLE session did not become ready'));
                this._handleDiscoverTimeout();
            }
        }, SCRUB_DISCOVERY_ACK_TIMEOUT_MS);

        request.then(() => {
            window.clearTimeout(this._scrubDiscoveryAckTimer);
            this._scrubDiscoveryAckTimer = null;
            this._discoverTimeoutID = window.setTimeout(this._handleDiscoverTimeout.bind(this), 15000);
        }).catch(error => {
            window.clearTimeout(this._scrubDiscoveryAckTimer);
            this._scrubDiscoveryAckTimer = null;
            this._handleRequestError(error);
        });
    }

    disconnect () {
        if (this._scrubDiscoveryAckTimer) {
            window.clearTimeout(this._scrubDiscoveryAckTimer);
            this._scrubDiscoveryAckTimer = null;
        }
        this._connected = false;
        if (this._socket.isOpen()) this._socket.close();
        if (this._discoverTimeoutID) window.clearTimeout(this._discoverTimeoutID);
        this._runtime.emit(this._runtime.constructor.PERIPHERAL_DISCONNECTED);
    }

    isConnected () {
        return this._connected;
    }

    connectPeripheral (id) {
        this.sendRemoteRequest('connect', {peripheralId: id}).then(() => {
            this._connected = true;
            this._runtime.emit(this._runtime.constructor.PERIPHERAL_CONNECTED);
            this._connectCallback();
        }).catch(error => this._handleRequestError(error));
    }

    startNotifications (serviceId, characteristicId, onCharacteristicChanged = null) {
        this._characteristicDidChangeCallback = onCharacteristicChanged;
        return this.sendRemoteRequest('startNotifications', {serviceId, characteristicId})
            .catch(error => this.handleDisconnectError(error));
    }

    write (serviceId, characteristicId, message, encoding = null, withResponse = null) {
        const params = {serviceId, characteristicId, message};
        if (encoding) params.encoding = encoding;
        if (withResponse !== null) params.withResponse = withResponse;
        return this.sendRemoteRequest('write', params).catch(error => {
            this.handleDisconnectError(error);
            throw error;
        });
    }

    didReceiveCall (method, params) {
        switch (method) {
        case 'didDiscoverPeripheral':
            this._availablePeripherals[params.peripheralId] = params;
            this._runtime.emit(this._runtime.constructor.PERIPHERAL_LIST_UPDATE, this._availablePeripherals);
            if (this._discoverTimeoutID) window.clearTimeout(this._discoverTimeoutID);
            break;
        case 'userDidPickPeripheral':
            this._availablePeripherals[params.peripheralId] = params;
            this._runtime.emit(this._runtime.constructor.USER_PICKED_PERIPHERAL, this._availablePeripherals);
            if (this._discoverTimeoutID) window.clearTimeout(this._discoverTimeoutID);
            break;
        case 'userDidNotPickPeripheral':
            this._runtime.emit(this._runtime.constructor.PERIPHERAL_SCAN_TIMEOUT);
            if (this._discoverTimeoutID) window.clearTimeout(this._discoverTimeoutID);
            break;
        case 'characteristicDidChange':
            if (this._characteristicDidChangeCallback) this._characteristicDidChangeCallback(params.message);
            break;
        case 'ping':
            return 42;
        }
    }

    handleDisconnectError () {
        if (!this._connected) return;
        this.disconnect();
        if (this._resetCallback) this._resetCallback();
        this._runtime.emit(this._runtime.constructor.PERIPHERAL_CONNECTION_LOST_ERROR, {
            message: 'Scratch lost connection to', extensionId: this._extensionId
        });
    }

    _handleRequestError () {
        this._runtime.emit(this._runtime.constructor.PERIPHERAL_REQUEST_ERROR, {
            message: 'Scratch lost connection to', extensionId: this._extensionId
        });
    }

    _handleDiscoverTimeout () {
        if (this._discoverTimeoutID) window.clearTimeout(this._discoverTimeoutID);
        this._runtime.emit(this._runtime.constructor.PERIPHERAL_SCAN_TIMEOUT);
    }
}

class RootProtocol {
    constructor () { this.packetId = 0; }

    static hexToBytes (text) {
        const clean = String(text || '').replace(/[^0-9a-f]/gi, '');
        if (clean.length % 2) throw new Error('16進数は2桁単位で指定してください');
        return Uint8Array.from(clean.match(/.{2}/g)?.map(value => parseInt(value, 16)) || []);
    }

    packet (device, command, payload = []) {
        const result = new Uint8Array(20);
        result[0] = device & 0xFF;
        result[1] = command & 0xFF;
        result[2] = this.packetId;
        this.packetId = (this.packetId + 1) & 0xFF;
        result.set(Uint8Array.from(payload).slice(0, 16), 3);
        result[19] = crc8(result.slice(0, 19));
        return result;
    }

    int32Payload (values) {
        const payload = new Uint8Array(values.length * 4);
        const view = new DataView(payload.buffer);
        values.forEach((value, index) => view.setInt32(index * 4, Math.round(value), false));
        return payload;
    }

    motors (left, right) { return this.packet(1, 4, this.int32Payload([clamp(left, -100, 100), clamp(right, -100, 100)])); }
    driveDistance (distanceMm) { return this.packet(1, 8, this.int32Payload([distanceMm])); }
    rotate (angleDeciDegrees) { return this.packet(1, 12, this.int32Payload([angleDeciDegrees])); }
    resetPosition () { return this.packet(1, 15); }
    navigateTo (xMm, yMm, headingDeciDegrees = -1) {
        const payload = new Uint8Array(10);
        const view = new DataView(payload.buffer);
        view.setInt32(0, Math.round(clamp(xMm, -0x80000000, 0x7FFFFFFF)), false);
        view.setInt32(4, Math.round(clamp(yMm, -0x80000000, 0x7FFFFFFF)), false);
        const heading = Number(headingDeciDegrees) === -1 ? -1 :
            Math.round(clamp(headingDeciDegrees, 0, 3599));
        view.setInt16(8, heading, false);
        return this.packet(1, 17, payload);
    }
    driveArc (angleDeciDegrees, radiusMm) { return this.packet(1, 27, this.int32Payload([angleDeciDegrees, radiusMm])); }
    led (state, red, green, blue) {
        return this.packet(3, 2, [clamp(state, 0, 3), clamp(red, 0, 255), clamp(green, 0, 255), clamp(blue, 0, 255)]);
    }

    note (frequency, durationMs) {
        const payload = new Uint8Array(6);
        const view = new DataView(payload.buffer);
        view.setUint32(0, clamp(frequency, 0, 0xFFFFFFFF), false);
        view.setUint16(4, clamp(durationMs, 0, 0xFFFF), false);
        return this.packet(5, 0, payload);
    }

    sayPhrase (phrase) {
        const payload = new Uint8Array(16);
        const encoder = new TextEncoder();
        let offset = 0;
        // Protocol payloads are limited to 16 UTF-8 bytes. Add complete
        // Unicode code points only, so truncation never leaves malformed
        // Japanese text or half of an emoji in the packet.
        for (const character of String(phrase)) {
            const encoded = encoder.encode(character);
            if (offset + encoded.length > payload.length) break;
            payload.set(encoded, offset);
            offset += encoded.length;
        }
        return this.packet(5, 4, payload);
    }

    setName (name) {
        const payload = new Uint8Array(16);
        const encoder = new TextEncoder();
        let offset = 0;
        for (const character of String(name)) {
            const encoded = encoder.encode(character);
            if (offset + encoded.length > payload.length) break;
            payload.set(encoded, offset);
            offset += encoded.length;
        }
        // The protocol requires a terminator when the name is shorter than
        // the 16-byte payload. A full 16-byte name uses all available bytes.
        if (offset < payload.length) payload[offset] = 0;
        return this.packet(0, 1, payload);
    }

    getName () {
        return this.packet(0, 2);
    }

    decode (packet) {
        const bytes = Uint8Array.from(packet);
        if (bytes.length !== 20 || crc8(bytes.slice(0, 19)) !== bytes[19]) return null;
        const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
        const result = {device: bytes[0], command: bytes[1], packetId: bytes[2], raw: bytesToHex(bytes)};
        if (bytes[0] === 14 && (bytes[1] === 0 || bytes[1] === 1)) {
            result.batteryMv = view.getUint16(7, false); result.batteryPercent = bytes[9];
        } else if (bytes[0] === 12 && bytes[1] === 0) {
            result.leftBumper = Boolean(bytes[7] & 0x80); result.rightBumper = Boolean(bytes[7] & 0x40);
        } else if (bytes[0] === 17 && bytes[1] === 0) {
            result.touchMask = bytes[7] >> 4;
        } else if (bytes[0] === 20 && bytes[1] === 0) {
            result.cliff = Boolean(bytes[7]);
        } else if (bytes[0] === 16 && bytes[1] === 1) {
            result.accelX = view.getInt16(7, false); result.accelY = view.getInt16(9, false); result.accelZ = view.getInt16(11, false);
        } else if (bytes[0] === 13 && (bytes[1] === 0 || bytes[1] === 1)) {
            result.lightLeft = view.getUint16(7, false); result.lightRight = view.getUint16(9, false);
        } else if (bytes[0] === 0 && bytes[1] === 2) {
            result.name = bytesToUtf8(bytes.slice(3, 19));
        }
        return result;
    }
}

class RootTransport {
    constructor (runtime, extensionId, onData, onReset = null, onConnected = null, onReady = null) {
        this.runtime = runtime;
        this.extensionId = extensionId;
        this.onData = onData;
        this.onReset = onReset;
        this.onConnected = onConnected;
        this.onReady = onReady;
        this.ble = null;
        this._writeTail = Promise.resolve();
        this.deviceName = '';
        this.mode = supportsWebBluetooth() ? 'Web Bluetooth' : 'Scratch Link / Scrub';
        this.lastError = '';
        this.runtime.registerPeripheralExtension(extensionId, this);
        this.onConnect = this.onConnect.bind(this);
        this.reset = this.reset.bind(this);
        this._registerRuntimeDiagnostics();
    }

    scan () {
        if (this.ble) this.ble.disconnect();
        this.lastError = '';
        const BLEAdapter = selectBLEAdapter();
        try {
            const options = {
                // Standard Scratch Link 2.x does not support Web Bluetooth's
                // manufacturerData filter shape. Root advertises this service,
                // so one service filter works in Web Bluetooth, Scratch Link,
                // and the Scrub bridge.
                ...ROOT_DISCOVERY_OPTIONS
            };
            const ScrubSocket = BLEAdapter === ScratchLinkBLE ? getScrubSocketClass() : null;
            this.ble = ScrubSocket ?
                new RootScratchLinkBLE(
                    this.runtime, this.extensionId, options, this.onConnect, this.reset, ScrubSocket
                ) :
                new BLEAdapter(this.runtime, this.extensionId, options, this.onConnect, this.reset);
        } catch (error) {
            this.setError(error);
            throw error;
        }
    }

    connect (peripheralId) {
        const peripheral = this.ble && this.ble._availablePeripherals && this.ble._availablePeripherals[peripheralId];
        const webDevice = this.ble && this.ble._device;
        this.deviceName = (peripheral && (peripheral.name || peripheral.localName)) ||
            (webDevice && webDevice.name) || '';
        if (this.ble) this.ble.connectPeripheral(peripheralId);
    }

    onConnect () {
        const startNotifications = this.ble.startNotifications(UART_SERVICE, TX, message => {
            this.onData(base64ToBytes(message));
        });
        if (this.onConnected) this.onConnected();
        if (this.onReady) Promise.resolve(startNotifications).then(() => this.onReady()).catch(error => this.setError(error));
    }

    write (bytes) {
        if (!this.isConnected()) return Promise.reject(new Error('Rootに接続してください'));
        const encoded = bytesToBase64(bytes);
        let resolveWrite;
        let rejectWrite;
        const result = new Promise((resolve, reject) => {
            resolveWrite = resolve;
            rejectWrite = reject;
        });

        // Each RootTransport has its own tail, so one Root cannot reorder or
        // suppress another Root's packets. Release the queue on either the
        // adapter's completion or a short bounded interval. The latter is
        // required for Scrub/Scratch Link implementations whose JSON-RPC
        // write request may remain pending after the BLE bytes were accepted.
        const previous = this._writeTail || Promise.resolve();
        const queued = previous.then(() => new Promise(resolveQueue => {
            let released = false;
            const release = () => {
                if (released) return;
                released = true;
                resolveQueue();
            };
            const setTimer = typeof window === 'undefined' ? setTimeout : window.setTimeout.bind(window);
            const clearTimer = typeof window === 'undefined' ? clearTimeout : window.clearTimeout.bind(window);
            const releaseTimer = setTimer(release, UART_WRITE_GAP_MS);
            let pendingWrite;
            try {
                pendingWrite = this.ble.write(UART_SERVICE, RX, encoded, 'base64', false);
            } catch (error) {
                clearTimer(releaseTimer);
                this.setError(error);
                rejectWrite(error);
                release();
                return;
            }
            Promise.resolve(pendingWrite).then(value => {
                clearTimer(releaseTimer);
                resolveWrite(value);
                release();
            }).catch(error => {
                clearTimer(releaseTimer);
                this.setError(error);
                rejectWrite(error);
                release();
            });
        }));
        // A failed packet must not poison the following packets in this
        // session. The returned `result` still reports that individual error.
        this._writeTail = queued.catch(() => undefined);
        return result;
    }

    disconnect () {
        if (this.ble) this.ble.disconnect();
        this.reset();
    }

    reset () {
        this.lastError = '';
        this.deviceName = '';
        if (this.onReset) this.onReset();
    }
    setError (error) {
        this.lastError = error && error.message ? error.message : String(error || 'BLE通信エラー');
    }
    _registerRuntimeDiagnostics () {
        if (!this.runtime.on) return;
        const RuntimeClass = this.runtime.constructor;
        this.runtime.on(RuntimeClass.PERIPHERAL_CONNECTED, () => {
            this.lastError = '';
        });
        this.runtime.on(RuntimeClass.PERIPHERAL_REQUEST_ERROR, details => {
            if (!details || !details.extensionId || details.extensionId === this.extensionId) {
                this.lastError = `${this.mode}: BLE接続要求に失敗しました`;
            }
        });
        this.runtime.on(RuntimeClass.PERIPHERAL_SCAN_TIMEOUT, () => {
            // Scratch VM does not include extensionId in this legacy event.
            // Session transports must not turn another Root's scan timeout
            // into their own connection error.
            if (this.extensionId.includes(':session:')) return;
            this.lastError = `${this.mode}: Rootが見つかりませんでした`;
        });
        this.runtime.on(RuntimeClass.PERIPHERAL_CONNECTION_LOST_ERROR, details => {
            if (!details || !details.extensionId || details.extensionId === this.extensionId) {
                this.lastError = `${this.mode}: Rootとの接続が失われました`;
            }
        });
    }
    isConnected () { return Boolean(this.ble && this.ble.isConnected()); }
}

export {
    ROOT_DISCOVERY_OPTIONS,
    RootProtocol,
    RootScratchLinkBLE,
    RootTransport,
    UART_WRITE_GAP_MS,
    SCRUB_DISCOVERY_ACK_ATTEMPTS,
    SCRUB_DISCOVERY_ACK_TIMEOUT_MS,
    base64ToBytes,
    bytesToBase64,
    crc8,
    getScrubSocketClass,
    selectBLEAdapter,
    supportsWebBluetooth
};
